




ALTER TABLE `zqzt_jt_notice_record` MODIFY COLUMN `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间' AFTER `create_time`;
ALTER TABLE zqzt_jt_notice_record ADD COLUMN retry_count INT DEFAULT 0 COMMENT '重试次数' AFTER res_body;
ALTER TABLE `zqzt_grp_group_info` ADD INDEX `idx_zqzt_grp_group_info_hq_grp_code`(`HQ_GRP_CODE`) USING BTREE;


-- RPA业务重试配置表
CREATE TABLE `zqzt_rpa_business_retry_config` (
                                                  `id` BIGINT(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
                                                  `biz_code` VARCHAR(64) NOT NULL COMMENT '业务类型编码',
                                                  `retry_interval_seconds` INT(11) DEFAULT 60 COMMENT '重试间隔(秒)',
                                                  `max_retry_count` INT(11) DEFAULT 3 COMMENT '最大重试次数, 999表示无限重试',
                                                  `is_enabled` TINYINT(1) DEFAULT 1 COMMENT '是否启用: 0-否, 1-是',
                                                  `remark` VARCHAR(500) DEFAULT NULL COMMENT '备注',
                                                  `create_time` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                                  `update_time` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                                  PRIMARY KEY (`id`),
                                                  UNIQUE KEY `uk_biz_code` (`biz_code`),
                                                  KEY `idx_is_enabled` (`is_enabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='RPA业务重试配置表';
